import java.io.*;

public class Rock_Paper_Scissors {
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        long[] a = new long[3];
        long[] b = new long[3];
        for (int i = 0; i < 3; i++) a[i] = fs.nextLong();
        for (int i = 0; i < 3; i++) b[i] = fs.nextLong();

        long min = 0;
        if (a[0] > b[0] + b[2]) min += a[0] - b[0] - b[2];
        if (a[1] > b[0] + b[1]) min += a[1] - b[0] - b[1];
        if (a[2] > b[1] + b[2]) min += a[2] - b[1] - b[2];

        long max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        System.out.println(min + " " + max);
    }

    static class FastScanner {
        long nextLong() throws IOException {
            long x = 0;
            int c;
            do {
                c = System.in.read();
            } while (c <= ' ' && c != -1);
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = System.in.read();
            }
            while (c > ' ') {
                x = x * 10 + (c - '0');
                c = System.in.read();
            }
            return neg ? -x : x;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
